select count(1) "次数",count(distinct g1.guid) "人数" from gather.gather g1 inner join gather.gather g2 on g1.guid=g2.guid
where g1.eventName={{eventName1}} and g1.createTime between {{eventStartTime1}} and {{eventEndTime1}}
and g2.eventName={{eventName2}} and g2.createTime between {{eventStartTime2}} and {{eventEndTime2}}

select trunc(r.days/30) months1,count(*) "次数",count(distinct r.uid) "人数"
from elt_user_vip_recharge_log r where r.rechargeType in (3,5) and r.vipType =2 and r.createdTime<{{eventStartTime}} and r.uid in (
	select distinct uid from elt_film_order where guid in (select distinct guid from gather.gather where eventName={{eventName}} and createTime between {{eventStartTime}} and {{eventEndTime}} and guid!='') 
)
group by months1
order by months1
